    /** iOS `SpeechScriptEngine.genreBrief`, by the genre's raw value; "" for an unknown one. */
    fun speechGenreBrief(genre: String): String =
            when (genre) {
                "explainer" -> "EXPLAINER — how or why something works (science, technology, the body, money, history). Build from what the listener already knows to the one idea that makes it click."
                "product" -> "PRODUCT INTRODUCTION — present a real product, invention or service: the problem it solves, how it works, what makes it different, who it is for. Informative, not an advert: no hype words, include one honest limitation."
                "person" -> "PERSON INTRODUCTION — introduce a real person (living or historical): who they are, the one thing they are known for, a telling detail or turning point, and why they matter today."
                "briefing" -> "INFORMATION BRIEFING — a practical, useful briefing (a health finding, a travel rule, a how-to, a cultural custom) delivered like a presenter: what it is, what to know, what to do."
                "own" -> "A SCRIPT ON THE SUBJECT GIVEN — the shape that fits it best."
                "news" -> "NEWS ANCHOR READ — a neutral news-style report on a recent, real development: lead with the headline fact, then context, then what happens next. Neutral tone, no opinion."
                else -> ""
            }

