    /** iOS `WeeklyTestEngine.translateItems`'s system prompt. */
    fun weeklyTranslateSystem(targetName: String, nativeName: String, level: String, maxTranslate: Int, topics: String): String =
            "You write a short translation quiz for a " +
            targetName +
            " learner whose own language is " +
            nativeName +
            ", level " +
            level +
            ". They answer by laying word tiles in order. You get mistakes they really made. Pick up to " +
            maxTranslate +
            " of them, each a DIFFERENT grammar point (skip pure word choice or a slip with no rule behind it), and for each write ONE new everyday sentence that cannot be said right without that grammar point.\n\nReturn {\"items\":[{\"source\":n,\"point\":\"...\",\"native\":\"...\",\"answer\":\"...\",\"orders\":[\"...\"],\"decoys\":[\"...\"],\"tip\":\"...\"}]}\n- source: the number of the mistake it is built on.\n- native: the sentence in " +
            nativeName +
            ", casual and spoken, the way they'd   say it to a friend, 6–12 words, about ordinary life (these were their   topics: " +
            topics +
            "). NOT their original sentence.\n- answer: the most natural " +
            targetName +
            " way to say it, at their level,   5–12 words. Its words are the tiles, so there must be ONE wording: no   optional words, nothing a learner could naturally say differently   with other words.\n- orders: every OTHER order of exactly the same words that is just as   correct. Go through each time, place and duration phrase (\"for two   years\", \"yesterday\", \"at midnight\") and each adverb, and list the   sentence with it at the front too wherever that is natural — a   learner who lays a right order and is marked wrong stops trusting   the test. [] only if the order is truly fixed.\n- decoys: 2–3 single words built from their mistake (e.g. \"since\", \"am\"   for \"I am working here since 2020\") that make the sentence WRONG   wherever they go, and are not in answer.\n- point: the grammar point in " +
            nativeName +
            ", 2–5 words. tip: one line in   " +
            nativeName +
            " on when it applies, at most 14 words.\nJSON only."

    /** iOS `WeeklyTestEngine.orderIsNatural`'s system prompt. */
    fun weeklyOrderSystem(name: String): String =
